import re

def parse(lines):
    blocks = []
    skip = []
    n = len(lines)
    i = 0
    while i < n:
        l = lines[i]
        if l.strip() and i + 1 < n and re.match(r'^\s*-+(\s+-+)*\s*$', lines[i + 1]):
            dash = lines[i + 1]
            starts = [m.start() for m in re.finditer(r'-+', dash)]
            names = []
            for k, s in enumerate(starts):
                if k + 1 < len(starts):
                    names.append(l[s:starts[k + 1]].strip())
                else:
                    names.append(l[s:].strip())
            idx = [i, i + 1]
            recs = []
            j = i + 2
            while j < n and lines[j].strip() and not re.match(r'^PS [^>]*>', lines[j]):
                t = lines[j]
                bs = []
                prev = 0
                for s in starts[1:]:
                    b = s
                    if b < len(t):
                        while b > prev and t[b - 1] != ' ' and t[b] != ' ':
                            b -= 1
                    bs.append(b)
                    prev = b
                cuts = [0] + bs
                rec = {}
                for k, nm in enumerate(names):
                    if k + 1 < len(cuts):
                        rec[nm] = t[cuts[k]:cuts[k + 1]].strip()
                    else:
                        rec[nm] = t[cuts[k]:].strip()
                recs.append(rec)
                idx.append(j)
                j += 1
            blocks.append({'name': 'adapters', 'kind': 'table', 'lines': idx, 'records': recs})
            i = j
            continue
        if l.strip():
            skip.append(i)
        i += 1
    return {'blocks': blocks, 'skip': skip}
